// Validate & flatten retry orders from Vercel
const inputItems = $input.all();
const orders = [];

for (const item of inputItems) {
  const data = item.json;
  if (Array.isArray(data)) {
    orders.push(...data);
  } else if (data && typeof data === 'object') {
    orders.push(data);
  }
}

const now = new Date().toISOString();
const validatedOrders = [];

for (const order of orders) {
  // Double-check retry conditions
  if (order.next_retry_at && order.next_retry_at <= now && (order.retry_count || 0) < 3) {
    validatedOrders.push(order);
  }
}

console.log(`[Retry Path] Validated ${validatedOrders.length} retry-ready order(s)`);

if (validatedOrders.length === 0) {
  return [];
}

return validatedOrders.map(order => ({ json: order }));

// Prepare order for router
const order = $input.first().json;

return [{
  json: {
    orderId: order.amazon_order_id,
    characterHash: order.character_hash || null,
    characterSpecs: order.character_specs,
    orderDbId: order.id,
    workflow: order.next_workflow || '2A',
    isRetry: true,
    retryCount: order.retry_count,
    _workType: order._workType || 'retry' // Preserve for merge node
  }
}];

// Log retry attempt
const order = $input.first().json;

console.log(`[Retry Path] 🔄 Retrying order ${order.orderId || order.amazon_order_id} (attempt ${(order.retryCount || 0) + 1})`);
console.log(`[Retry Path] Workflow: ${order.workflow || order.next_workflow || '2A'}`);
console.log(`[Retry Path] Order DB ID: ${order.orderDbId || order.id}`);

return [{ json: order }];

// Classify orphaned orders and determine recovery action
const inputItems = $input.all();
const orders = [];

for (const item of inputItems) {
  const data = item.json;
  if (Array.isArray(data)) {
    orders.push(...data);
  } else if (data && typeof data === 'object') {
    orders.push(data);
  }
}

if (orders.length === 0) {
  return [];
}

const classified = orders.map(order => {
  const reason = order.orphan_reason;
  let action = null;
  let priority = 'low';

  // First, check the orphan_reason to determine the primary action
  switch (reason) {
    case 'error_no_retry_scheduled':
      if ((order.retry_count || 0) < 3) {
        action = 'schedule_retry';
        priority = 'high';
      } else {
        action = 'require_manual_review';
        priority = 'medium';
      }
      break;
    case 'error_max_retries_exceeded':
      action = 'require_manual_review';
      priority = 'high';
      break;
    case 'processing_stuck_over_hour':
    case 'processing_no_timestamp':
      action = 'reset_to_error_and_retry';
      priority = 'high';
      break;
    case 'ready_not_picked_up':
      // Orders ready but not picked up - check if they need manifest or just need router to pick them up
      // If at workflow 4 and missing manifest, that's a real issue
      // Otherwise, just reset to let router pick them up
      if (order.next_workflow === '4' && !order.one_manifest_url) {
        // At workflow 4 but missing manifest - this is a real problem
        action = 'require_manual_review';
        priority = 'high';
      } else {
        // Just needs router to pick it up - reset processing status
        action = 'reset_processing';
        priority = 'medium';
      }
      break;
    case 'manual_review_pending':
      // Already in manual review, just needs human attention
      action = 'require_manual_review';
      priority = 'medium';
      break;
    default:
      // For unknown reasons, check if missing manifest is the issue
      if (!order.one_manifest_url && order.next_workflow && ['3', '4'].includes(String(order.next_workflow))) {
        action = 'create_manifest';
        priority = 'high';
      } else {
        action = 'require_manual_review';
        priority = 'low';
      }
  }

  return {
    ...order,
    action,
    priority
  };
});

return classified.map(order => ({ json: order }));

// Route orders by action type
const orders = $input.all().map(item => item.json);

const scheduleRetry = [];
const manualReview = [];
const resetProcessing = [];
const createManifest = [];

for (const order of orders) {
  if (order.action === 'create_manifest') {
    createManifest.push(order);
  } else if (order.action === 'schedule_retry') {
    scheduleRetry.push(order);
  } else if (order.action === 'require_manual_review') {
    manualReview.push(order);
  } else if (order.action === 'reset_to_error_and_retry' || order.action === 'reset_processing') {
    resetProcessing.push(order);
  } else {
    // Unknown action - send to manual review
    manualReview.push(order);
  }
}

console.log(`[Orphaned Route] Routing ${orders.length} orders: ${createManifest.length} create_manifest, ${scheduleRetry.length} schedule_retry, ${manualReview.length} manual_review, ${resetProcessing.length} reset_processing`);

return [
  ...createManifest.map(o => ({ json: { ...o, _route: 'create_manifest' } })),
  ...scheduleRetry.map(o => ({ json: { ...o, _route: 'schedule_retry' } })),
  ...manualReview.map(o => ({ json: { ...o, _route: 'manual_review' } })),
  ...resetProcessing.map(o => ({ json: { ...o, _route: 'reset_processing' } }))
];

// Handle Create Manifest - classify successes and failures
// This node receives ALL items from Create Manifest node (both success and error)
// With continueOnFail: true, errors are included in main output with error property
const inputItems = $input.all();
const allOrders = [];

for (const item of inputItems) {
  const data = item.json;

  // Check if this is an error response
  // n8n marks failed items with item.error or data.errorMessage
  if (item.error || (data.errorMessage || data.error)) {
    console.error(`[Create Manifest Failure] Order ${data.amazon_order_id || data.id}: Create manifest failed`);
    console.error(`  Error: ${data.errorMessage || data.error || 'Unknown error'}`);

    // Mark for manual review
    allOrders.push({
      ...data,
      _route: 'manual_review',
      recovery_failed: true,
      recovery_error: data.errorMessage || data.error || 'Create manifest failed'
    });
  } else {
    // Success - manifest was created
    console.log(`[Create Manifest Success] Order ${data.amazon_order_id || data.id}: Manifest created successfully`);
    allOrders.push(data);
  }
}

console.log(`[Handle Create Manifest] Processed ${allOrders.length} order(s): ${allOrders.filter(o => o._route === 'manual_review').length} failures, ${allOrders.filter(o => !o._route).length} successes`);

// Return all items - IF node will route based on _route property
return allOrders.map(order => ({ json: order }));

