// Accumulate items from all branches using execution custom data
// This node executes once per branch, so we accumulate items and only process when all branches complete
const inputItems = $input.all();

// Initialize execution custom data if needed
if (!$execution.customData) {
  $execution.customData = {};
}
if (!$execution.customData.healthMonitorItems) {
  $execution.customData.healthMonitorItems = [];
  $execution.customData.healthMonitorBranches = new Set();
}

// Add all items from this branch to accumulator
for (const item of inputItems) {
  $execution.customData.healthMonitorItems.push(item);
}

// Track which branch this is (by checking which node sent items)
// We expect 3 branches: Schedule Retry, Mark for Manual Review, Reset Processing
const currentNodeName = $node.name;
console.log(`[Accumulator] Node: ${currentNodeName}, received ${inputItems.length} item(s)`);

// Mark this branch as processed
$execution.customData.healthMonitorBranches.add(currentNodeName);

// Check if we've received items from all expected branches
// We expect items from: Orphaned: Recover: Schedule Retry, Orphaned: Recover: Mark for Manual Review, Orphaned: Recover: Reset Processing
// But also from: Stuck paths, Retry paths, and Create Manifest success path
// Actually, we can't reliably detect all branches, so we'll process after a short delay or when we have items

const totalAccumulated = $execution.customData.healthMonitorItems.length;
console.log(`[Accumulator] Total accumulated: ${totalAccumulated} item(s) from ${$execution.customData.healthMonitorBranches.size} branch(es)`);

// For now, just pass through - we'll process in a separate node
// Return empty to prevent duplicate processing
return [];

// Alert: Health Monitor Summary
const summary = $input.first().json;

console.log('\n=== HEALTH MONITOR SUMMARY ===');
console.log(`Timestamp: ${summary.timestamp}`);
console.log(`\nStuck Orders Processed: ${summary.stuck.count}`);
if (summary.stuck.count > 0) {
  console.log(`  Orders: ${summary.stuck.orders.join(', ')}`);
}
console.log(`\nRetry Orders Processed: ${summary.retries.count}`);
if (summary.retries.count > 0) {
  console.log(`  Orders: ${summary.retries.orders.join(', ')}`);
}
console.log(`\nOrphaned Orders Processed: ${summary.orphaned.count}`);
if (summary.orphaned.count > 0) {
  console.log(`  Orders: ${summary.orphaned.orders.join(', ')}`);
}
if (summary.unclassified && summary.unclassified.count > 0) {
  console.error(`\n⚠️  UNCLASSIFIED ITEMS: ${summary.unclassified.count}`);
  console.error(`  Items: ${summary.unclassified.items.join(', ')}`);
  console.error('  This indicates a potential issue with work type identification!');
}
console.log(`\nTotal Items Processed: ${summary.total}`);
console.log('==============================\n');

// TODO: Send to Slack/Email/Dashboard

return [{ json: summary }];
